head.script:
scwin.__checkErrLog = function() {
    var log = WebSquare.logger.getErrorLog();
    return log.indexOf("scwin.udc_search_onSearch is not a function") == -1
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일(wframe_udc_SKT-288_(WSQ-930)_main.xml) 실행 후 검색버튼을 클릭한다.
    //1. Run the sample file (wframe_udc_SKT-288_ (WSQ-930) _main.xml) and click the Search button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('wfm_sub1_udc_search_btn_search').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 1. 정상적인 알림창(Occur udc_search_onSearch)이 발생한다.
    //1. A normal alert (Occur udc_search_onSearch) occurs.
    WebSquare.wUnit.addCommand("assert", "log", "Occur udc_search_onSearch");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 실행화면에서 ctrl+마우스우클릭으로 로그보기를 실행한다. 
    //2. Execute the log view with ctrl + right click on the execution screen.                
    //Verify 2. 정상적인 로그가 보여진다.(이전에 scwin.udc_search_onSearch is not a function) 오류 메시지 발생
    //2. The normal log is displayed (previously scwin.udc_search_onSearch is not a function)
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 01-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
